INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('42e06de0-ce4c-4e60-9adc-f3f471485981', 'ACP-Q-1601', 1, 'published', 'p-mpharm', 'sub-electrolytes', 'medium', 'sba', 'hospital', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('ba6db0f1-c1dd-4844-8131-e5eee3cf9f0b', '42e06de0-ce4c-4e60-9adc-f3f471485981', 'A 35-year-old female with microcytic hypochromic anaemia is prescribed Ferrous sulfate 200 mg tablets (65 mg elemental iron). She complains of severe constipation and nausea when taking it three times daily. (Case Ref: BLOOD-NUTRITION-1601). Relevant physiological and medication history have been reviewed.', 'What evidence-based modification improves tolerance and maintains iron absorption?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('59a2934d-49f9-472d-960c-c35f222bde18', '42e06de0-ce4c-4e60-9adc-f3f471485981', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c5501ce7-477d-4406-ba45-fcfbc9d613d3', '42e06de0-ce4c-4e60-9adc-f3f471485981', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5fc2d042-8508-452a-aef5-fe2a5a9b4cee', '42e06de0-ce4c-4e60-9adc-f3f471485981', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('338d07f7-d9cd-4bee-85a5-74f0c38809fd', '42e06de0-ce4c-4e60-9adc-f3f471485981', 'D', 'Prescribe high-dose oral iron 200 mg four times daily', 0, 'Deprecated. High doses stimulate hepcidin and block subsequent iron transport, maximizing nausea without therapeutic gain.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f97641fc-81d8-4f5c-94e1-70f66e13b2f9', '42e06de0-ce4c-4e60-9adc-f3f471485981', 'E', 'Check ferritin and haemoglobin 48 hours after starting iron therapy', 0, 'Inappropriate timing. Reticulocytosis takes 5-7 days; significant Hb rise takes 2 to 4 weeks.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('f6f621d9-4165-459f-9918-a881efa8a0c9', '42e06de0-ce4c-4e60-9adc-f3f471485981', 'Alternate-day or once-daily oral iron improves absorption and GI tolerance. Avoid modified-release iron preparations.', 'Target rise in haemoglobin is approximately 2 g/100 mL every 3 to 4 weeks. Reference: BNF Section 9.1.1 & British Society of Gastroenterology.', 'BNF Section 9.1.1 & British Society of Gastroenterology', 1789734485, 1789734485);
