INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('5fb9de4d-3c9f-49e8-9cb8-f872b4957abe', '072bd217-bd1d-4673-b089-935ee94e06b8', 'A 35-year-old female with microcytic hypochromic anaemia is prescribed Ferrous sulfate 200 mg tablets (65 mg elemental iron). She complains of severe constipation and nausea when taking it three times daily. (Case Ref: BLOOD-NUTRITION-1629). Relevant physiological and medication history have been reviewed.', 'What evidence-based modification improves tolerance and maintains iron absorption?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5eb8cfab-6561-40ad-b017-7315ca0ba9f6', '072bd217-bd1d-4673-b089-935ee94e06b8', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5a60b61a-6a67-4378-9a54-0e95e0cdd595', '072bd217-bd1d-4673-b089-935ee94e06b8', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('98e36f00-1b2c-4895-992c-dd39c9ff94df', '072bd217-bd1d-4673-b089-935ee94e06b8', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('fa22e117-49f8-4add-955f-6f040405d19e', '072bd217-bd1d-4673-b089-935ee94e06b8', 'D', 'Prescribe high-dose oral iron 200 mg four times daily', 0, 'Deprecated. High doses stimulate hepcidin and block subsequent iron transport, maximizing nausea without therapeutic gain.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bc59aa65-1942-4808-8917-ec803fe20d1b', '072bd217-bd1d-4673-b089-935ee94e06b8', 'E', 'Check ferritin and haemoglobin 48 hours after starting iron therapy', 0, 'Inappropriate timing. Reticulocytosis takes 5-7 days; significant Hb rise takes 2 to 4 weeks.', 4, 1789734485);
