INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0fe17901-fe67-4222-8074-255decb48f43', 'af5b13b5-0c65-4749-8d00-3232ce29a035', 'D', 'Prescribe high-dose oral iron 200 mg four times daily', 0, 'Deprecated. High doses stimulate hepcidin and block subsequent iron transport, maximizing nausea without therapeutic gain.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0b4ef25a-4819-4bdc-9d73-cbd1f6e8d850', 'af5b13b5-0c65-4749-8d00-3232ce29a035', 'E', 'Check ferritin and haemoglobin 48 hours after starting iron therapy', 0, 'Inappropriate timing. Reticulocytosis takes 5-7 days; significant Hb rise takes 2 to 4 weeks.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('495e10c9-3917-426c-8a5c-e8d55f5d81aa', 'af5b13b5-0c65-4749-8d00-3232ce29a035', 'Alternate-day or once-daily oral iron improves absorption and GI tolerance. Avoid modified-release iron preparations.', 'Target rise in haemoglobin is approximately 2 g/100 mL every 3 to 4 weeks. Reference: BNF Section 9.1.1 & British Society of Gastroenterology.', 'BNF Section 9.1.1 & British Society of Gastroenterology', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('e7a9cd00-adeb-4ae1-afb0-b3aae74c5761', 'af5b13b5-0c65-4749-8d00-3232ce29a035', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);
