INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('1c1eb133-f390-46ea-9e53-83eae0114f8b', 'c53cbf11-9196-4313-91f6-3b378067540f', 'A 35-year-old female with microcytic hypochromic anaemia is prescribed Ferrous sulfate 200 mg tablets (65 mg elemental iron). She complains of severe constipation and nausea when taking it three times daily. (Case Ref: BLOOD-NUTRITION-1635). Relevant physiological and medication history have been reviewed.', 'What evidence-based modification improves tolerance and maintains iron absorption?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a9631418-34bd-4d66-bbe7-eb791e76463f', 'c53cbf11-9196-4313-91f6-3b378067540f', 'A', 'Reduce dosing frequency to 200 mg once daily or on alternate days, taken with water or vitamin C on an empty stomach', 1, 'Correct. Once-daily or alternate-day oral iron dosing minimizes hepcidin elevation, resulting in equal or superior fractional iron absorption with markedly fewer GI side effects.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2108b998-3064-4150-b8aa-6350eb28bb30', 'c53cbf11-9196-4313-91f6-3b378067540f', 'B', 'Instruct patient to take iron with a large glass of cow’s milk and a bowl of high-fibre cereal', 0, 'Sub-optimal. Calcium, tannins (tea/coffee), and phytates form insoluble chelates with iron and drastically diminish absorption.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6c64986b-3946-49a4-8106-a1d89c43703b', 'c53cbf11-9196-4313-91f6-3b378067540f', 'C', 'Switch to modified-release enteric-coated iron formulation for rapid correction', 0, 'Contraindicated under UK guidance. Enteric-coated iron carries the active ingredient past the duodenum and upper jejunum (the primary absorption site), reducing bioavailability and wasting resources.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('20ef74d7-3794-40e8-9cb4-80e86bee7f4f', 'c53cbf11-9196-4313-91f6-3b378067540f', 'D', 'Prescribe high-dose oral iron 200 mg four times daily', 0, 'Deprecated. High doses stimulate hepcidin and block subsequent iron transport, maximizing nausea without therapeutic gain.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e17f1a71-a6e8-49d8-902b-f819365843fb', 'c53cbf11-9196-4313-91f6-3b378067540f', 'E', 'Check ferritin and haemoglobin 48 hours after starting iron therapy', 0, 'Inappropriate timing. Reticulocytosis takes 5-7 days; significant Hb rise takes 2 to 4 weeks.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('6ada229d-f5d0-4bfa-8e03-58b781c9f78e', 'c53cbf11-9196-4313-91f6-3b378067540f', 'Alternate-day or once-daily oral iron improves absorption and GI tolerance. Avoid modified-release iron preparations.', 'Target rise in haemoglobin is approximately 2 g/100 mL every 3 to 4 weeks. Reference: BNF Section 9.1.1 & British Society of Gastroenterology.', 'BNF Section 9.1.1 & British Society of Gastroenterology', 1789734485, 1789734485);
