INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('38fa00be-2f18-4f7b-be01-8875a8eee913', 'f778b558-6531-4724-a566-dc2bb84e005d', 'A 32-year-old female at 16 weeks gestation is diagnosed with gestational hypertension (BP 154/98 mmHg). Proteinuria is negative. Past medical history is unremarkable. (Case Ref: OBSTETRICS-GYNAECOLOGY-1636). Relevant physiological and medication history have been reviewed.', 'Which antihypertensive medication is recommended first-line by NICE NG133?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b5ddd8d1-8da2-4d03-b1b6-fd04ea09e92a', 'f778b558-6531-4724-a566-dc2bb84e005d', 'A', 'Labetalol orally (or modified-release Nifedipine if labetalol is contraindicated/asthmatic)', 1, 'Correct. Labetalol is first-line for gestational hypertension. Nifedipine is second-line (or first-line if asthmatic). Methyldopa is third-line.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('63b5fcd5-f1a1-4cd8-8fdd-92a870306f02', 'f778b558-6531-4724-a566-dc2bb84e005d', 'B', 'Methyldopa 250 mg twice daily as initial choice', 0, 'Sub-optimal compared to labetalol due to maternal sedation, depression risk, and postural hypotension.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d57541a7-0a50-4e89-ab97-efe4f1cca5c7', 'f778b558-6531-4724-a566-dc2bb84e005d', 'C', 'Ramipril 5 mg once daily', 0, 'Strictly contraindicated. ACE inhibitors and ARBs cause severe fetopathy, oligohydramnios, skull hypoplasia, and neonatal renal failure.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a09c651e-e433-46c9-82ff-91370db4bb28', 'f778b558-6531-4724-a566-dc2bb84e005d', 'D', 'Atenolol 50 mg daily', 0, 'Deprecated in pregnancy due to association with fetal intrauterine growth restriction (IUGR).', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9c716378-391d-4b4c-8add-b0a2b3204560', 'f778b558-6531-4724-a566-dc2bb84e005d', 'E', 'Withhold all treatment until blood pressure exceeds 180/120 mmHg', 0, 'Dangerous inaction. Failure to treat severe hypertension increases placental abruption and maternal stroke risks.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('7643a968-8c6c-4bb0-803d-c95d7d69c534', 'f778b558-6531-4724-a566-dc2bb84e005d', 'Labetalol is first-line for pregnancy hypertension. ACE inhibitors and ARBs are strictly contraindicated in pregnancy.', 'Target blood pressure in pregnancy is 135/85 mmHg. Reference: NICE NG133: Hypertension in pregnancy: diagnosis and management.', 'NICE NG133: Hypertension in pregnancy: diagnosis and management', 1789734485, 1789734485);
