INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('0b8a70f8-2b70-4b28-80fb-a5685e5c5a3c', '16f3a825-19d8-4b91-87c7-11ce87474b96', 'A 42-year-old swimmer presents with left ear pain, discharge, and itch. Examination suggests localized otitis externa, but the tympanic membrane cannot be fully visualized and perforation cannot be ruled out. (Case Ref: ENT-1701). Relevant physiological and medication history have been reviewed.', 'Which ear drop preparation is safe to prescribe when tympanic perforation cannot be excluded?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7b1e6d73-0779-4663-8145-e292b6a39a02', '16f3a825-19d8-4b91-87c7-11ce87474b96', 'A', 'Ciprofloxacin 0.2% ear drops (non-aminoglycoside preparation)', 1, 'Correct. Aminoglycoside-containing drops (gentamicin, neomycin, framycetin) are contraindicated when the eardrum is perforated due to risk of permanent sensorineural hearing loss. Ciprofloxacin drops are non-ototoxic.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4f221f21-db0b-43a2-807f-ceb85b966d4a', '16f3a825-19d8-4b91-87c7-11ce87474b96', 'B', 'Gentisone HC (Gentamicin with Hydrocortisone) ear drops', 0, 'Contraindicated and dangerous. Aminoglycoside inner ear toxicity causes permanent deafness.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a040a186-5ba4-4c7e-9ff5-2a403f5058a5', '16f3a825-19d8-4b91-87c7-11ce87474b96', 'C', 'Neomycin and dexamethasone spray into middle ear cavity', 0, 'Contraindicated. High risk of ototoxicity if entering through perforation.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('07a63132-1d11-4f79-aa1d-4c69707d93f7', '16f3a825-19d8-4b91-87c7-11ce87474b96', 'D', 'Syringe ear vigorously with warm tap water to clear purulent discharge', 0, 'Dangerous and contraindicated in potential perforation.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d02012b3-3b0c-49a2-8ad3-f7dc4f874677', '16f3a825-19d8-4b91-87c7-11ce87474b96', 'E', 'Advise patient to insert cotton wool soaked in pure olive oil for 3 weeks without review', 0, 'Inappropriate and promotes bacterial growth in moist enclosed environment.', 4, 1789734485);
