INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('7139ba6a-e58e-4615-947f-546dce3420d2', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 'A 66-year-old male with newly diagnosed open-angle glaucoma has a documented medical history of severe brittle asthma with frequent exacerbations. (Case Ref: OPHTHALMOLOGY-1800). Relevant physiological and medication history have been reviewed.', 'Which first-line ocular pressure-lowering drop is most appropriate?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2c4691cd-f35a-4c87-b9fc-0695cbb644ef', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 'A', 'Latanoprost 50 mcg/mL eye drops once daily at night (prostaglandin analogue)', 1, 'Correct. Prostaglandin analogues are first-line for primary open-angle glaucoma and do not cause bronchospasm. Beta-blocker drops (timolol, betaxolol) are contraindicated in asthma.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('389a986a-6788-4261-b49d-f2e481da70a6', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 'B', 'Timolol 0.5% eye drops twice daily', 0, 'Strictly contraindicated. Systemic absorption of ocular beta-blockers via the nasolacrimal duct triggers life-threatening bronchospasm.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c06a0828-2ab4-4302-905f-aef214b55ec7', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 'C', 'Betaxolol 0.5% eye drops in patient with uncontrolled bronchospasm', 0, 'Unsafe. Even "cardioselective" beta-blocker drops can precipitate severe asthma attacks in sensitive individuals.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d59c625a-f666-40f6-b1d7-9ffa1a497a66', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 'D', 'Pilocarpine 2% drops four times daily as first-line maintenance', 0, 'Deprecated as first-line due to intense miosis, brow ache, and blurred vision.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a38a96d2-39d6-46da-abb5-cf05ec81df23', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 'E', 'Administer drops without educating on nasolacrimal occlusion (punctal pressure)', 0, 'Poor administration technique. Nasolacrimal pressure for 1-2 minutes reduces systemic drug absorption by up to 60%.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('3172556f-4f14-4d01-a54d-680b40713b08', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 'Ocular beta-blockers (Timolol) are contraindicated in asthma. Prostaglandin analogues (Latanoprost) are first-line.', 'Latanoprost counselling: irreversible brown iris darkening, eyelash lengthening, and peri-orbital fat atrophy. Reference: NICE NG81: Glaucoma: diagnosis and management.', 'NICE NG81: Glaucoma: diagnosis and management', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('44f1e579-4cd2-411c-88bf-6081e7dcd720', 'cff037d3-ec1c-475e-bdc1-830b33fc4f48', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);